"use client";

import { motion, useReducedMotion } from "framer-motion";

const MEDALLION = 64;
const HALF = MEDALLION / 2;

export function EmptyState({
  title,
  description,
  action,
}: {
  title: string;
  description: string;
  action?: { label: string; onClick?: () => void };
}) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <div className="relative flex w-full flex-col items-center gap-4 overflow-hidden rounded-2xl border border-slate-200 bg-white px-8 py-10 text-center dark:border-slate-700 dark:bg-neutral-950">
      <motion.span
        aria-hidden
        className="absolute inset-x-0 top-0 h-0.5 bg-slate-400 dark:bg-slate-500"
        initial={{ scaleX: 0 }}
        animate={{ scaleX: 1 }}
        transition={{ duration: 0.5, ease: [0.16, 1, 0.3, 1] }}
        style={{ transformOrigin: "center" }}
      />

      <div className="relative flex items-center justify-center" style={{ width: MEDALLION, height: MEDALLION }}>
        <motion.span
          aria-hidden
          className="absolute inset-0 rounded-full blur-md bg-slate-400/25 dark:bg-slate-400/15"
          animate={shouldReduceMotion ? { opacity: 0.3 } : { opacity: [0.15, 0.35, 0.15] }}
          transition={shouldReduceMotion ? { duration: 0.2 } : { duration: 2.6, repeat: Infinity, ease: "easeInOut" }}
        />

        {/* idle breathing rings: a continuous "waiting" signal */}
        {!shouldReduceMotion &&
          [0, 1.2].map((delay) => (
            <motion.span
              key={delay}
              aria-hidden
              className="absolute rounded-full border border-slate-300/70 dark:border-slate-500/40"
              style={{
                width: MEDALLION,
                height: MEDALLION,
                top: "50%",
                left: "50%",
                marginLeft: -HALF,
                marginTop: -HALF,
              }}
              initial={{ scale: 1, opacity: 0.4 }}
              animate={{ scale: 1.35, opacity: 0 }}
              transition={{ duration: 2.4, repeat: Infinity, ease: "easeOut", delay }}
            />
          ))}

        <div
          className="relative flex items-center justify-center rounded-full border border-slate-300 bg-slate-100 text-slate-400 dark:border-slate-600 dark:bg-neutral-900 dark:text-slate-500"
          style={{ width: MEDALLION, height: MEDALLION }}
        >
          <motion.svg
            viewBox="0 0 24 24"
            width="30"
            height="30"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            aria-hidden
            initial={{ opacity: 0 }}
            animate={shouldReduceMotion ? { opacity: 1 } : { opacity: 1, y: [0, -3, 0] }}
            transition={
              shouldReduceMotion
                ? { duration: 0.2 }
                : { opacity: { duration: 0.3 }, y: { duration: 2.4, repeat: Infinity, ease: "easeInOut", delay: 0.3 } }
            }
          >
            <path d="M3 8.5 6 4h12l3 4.5" />
            <path d="M3 8.5h18v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-9Z" />
            <path d="M8 12.5a2 2 0 0 0 2 2h4a2 2 0 0 0 2-2" />
          </motion.svg>
        </div>
      </div>

      <div className="flex flex-col gap-1.5">
        <h3 className="text-base font-semibold text-slate-900 dark:text-white">{title}</h3>
        <p className="text-sm leading-relaxed text-slate-500 dark:text-slate-400">{description}</p>
      </div>

      {action && (
        <motion.button
          onClick={action.onClick}
          whileHover={shouldReduceMotion ? undefined : { y: -2 }}
          whileTap={{ scale: 0.96, y: 0 }}
          transition={{ type: "spring", stiffness: 500, damping: 30 }}
          className="group relative mt-1 inline-flex items-center justify-center overflow-hidden rounded-lg bg-amber-700 px-4 py-2 text-sm font-medium text-white shadow-[0_1px_2px_rgba(180,83,9,0.3)] transition-[box-shadow,background-color] duration-300 hover:bg-amber-600 hover:shadow-[0_10px_20px_-8px_rgba(180,83,9,0.6)] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-amber-700"
        >
          <span
            aria-hidden
            className="pointer-events-none absolute inset-0 -translate-x-full bg-gradient-to-r from-transparent via-white/30 to-transparent transition-transform duration-700 ease-out group-hover:translate-x-full motion-reduce:hidden"
          />
          <span className="relative">{action.label}</span>
        </motion.button>
      )}
    </div>
  );
}
